# Based on the demo, I need to figure out the pattern
# Demo: 20x20 input → 3x3 output of all 4s
# The output is always 3x3 filled with one color from the input

# In the test input, I need to find which color to use
# Let me analyze the test input more carefully to understand the pattern

def analyze_grid(grid):
    print("=== Analyzing grid ===")

    # Find solid rectangular regions (blocks where the color is uniform within the bbox)
    for color in range(1, 10):  # 0 is usually background
        cells = []
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] == color:
                    cells.append((r, c))

        if not cells:
            continue

        r_min, r_max = min(r for r, _ in cells), max(r for r, _ in cells)
        c_min, c_max = min(c for _, c in cells), max(c for _, c in cells)

        # Check if it's a solid block
        is_solid = True
        solid_cells = []
        for r in range(r_min, r_max + 1):
            for c in range(c_min, c_max + 1):
                if grid[r][c] == color:
                    solid_cells.append((r, c))
                else:
                    is_solid = False

        if is_solid:
            height = r_max - r_min + 1
            width = c_max - c_min + 1
            print(f"Solid block of {color}: size {height}x{width} = {len(solid_cells)} cells")

    # Find total count of each color
    from collections import Counter
    color_counts = Counter()
    for row in grid:
        for c in row:
            color_counts[c] += 1

    print("\nTotal color counts:", dict(sorted(color_counts.items())))

    return analyze_grid

analyze_grid(input_grid)

