def find_solid_blocks(grid):
    print("=== Finding solid rectangular blocks ===")

    for color in sorted(set(0) | set(sum(row, []) for row in grid)):
        cells = []
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] == color:
                    cells.append((r, c))

        if not cells:
