        r_min, r_max = min(r for r, _ in cells), max(r for r, _ in cells)
        c_min, c_max = min(c for _, c in cells), max(c for _, c in cells)

        # Count cells in the bbox that match
        matching = sum(1 for r in range(r_min, r_max + 1) 
                       for c in range(c_min, c_max + 1) 
                       if grid[r][c] == color)

        total_in_bbox = (r_max - r_min + 1) * (c_max - c_min + 1)
        fill_ratio = matching / total_in_bbox if total_in_bbox > 0 else 0

        if fill_ratio >= 0.9:  # Consider it "solid" if at least 90% filled
            print(f"Color {color}: bbox=({r_min},{r_max}x{c_min},{c_max}), size={total_in_bbox}, match={matching}, ratio={fill_ratio:.2%}")

    # Find total count of each color
    color_counts = {}
    for row in grid:
        for c in row:
            color_counts[c] = color_counts.get(c, 0) + 1

    print("\ntotal color counts:", dict(sorted(color_counts.items())))

